css:
/* LIMETTA_BOOKING_FORM_SIMPLE_V1 */
.booking-note-toggle{margin-top:20px}
.booking-note-toggle summary{min-height:44px;display:flex;align-items:center;flex-wrap:wrap;column-gap:5px;cursor:pointer;list-style:none;color:#24336a;font-size:14px;text-decoration:underline;text-underline-offset:4px}
.booking-note-toggle summary::-webkit-details-marker{display:none}
.booking-note-toggle summary span{font-weight:400;color:#4f5570}
.booking-note-toggle summary:focus-visible{outline:3px solid #95c13b;outline-offset:4px;border-radius:4px}
.booking-note-toggle[open] summary{margin-bottom:8px}
.booking-note-toggle[open] label{margin-top:8px}
.booking-review{margin-top:24px;padding:20px;background:#f2f6e9;border-radius:10px}
.booking-review__label{margin:0 0 8px;font-size:12px;font-weight:600;color:#4f5570}
.booking-review #selected-slot{margin:0;font-size:17px;font-weight:700;line-height:1.5;font-variant-numeric:tabular-nums}
.booking-review__reassurance{margin:10px 0 0;font-size:13px;line-height:1.6;color:#4f5570}
